'use client';
import { useState, useEffect } from 'react';
import { use } from 'react';
import axios from 'axios';
import { useRouter } from 'next/navigation';
import { Save as SaveIcon, Clear as ClearIcon, Person as PersonIcon } from '@mui/icons-material';
import Layout from "../../../components/Layout";

export default function EditGroupe({ params }) {
  // Properly unwrap the async params
  const { id } = use(params);
  
  const [groupe, setGroupe] = useState(null);
  const [etudiants, setEtudiants] = useState([]);
  const [selectedEtudiants, setSelectedEtudiants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [nomGroupe, setNomGroupe] = useState('');
  const router = useRouter();

  useEffect(() => {
    if (id) {
      fetchData();
    }
  }, [id]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [groupeResponse, etudiantsResponse] = await Promise.all([
        axios.get(`http://localhost:5000/api/groupes/${id}`),
        axios.get('http://localhost:5000/api/etudiants')
      ]);

      const groupeData = groupeResponse.data;
      const eligibleStudents = etudiantsResponse.data.filter(e => 
        !e.idGroupe || e.idGroupe === groupeData.idGroupe
      );

      setGroupe(groupeData);
      setNomGroupe(groupeData.nomGroupe);
      setEtudiants(eligibleStudents);
      setSelectedEtudiants(groupeData.etudiants?.map(e => e.idEtudiant) || []);
    } catch (err) {
      console.error("Erreur lors de la récupération des données :", err);
      alert("Erreur lors du chargement des données du groupe");
    } finally {
      setLoading(false);
    }
  };

  const toggleSelection = (id) => {
    setSelectedEtudiants(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const updateGroupe = async () => {
    if (!nomGroupe.trim()) {
      alert("Le nom du groupe est requis");
      return;
    }

    try {
      // Update group name
      await axios.put(`http://localhost:5000/api/groupes/${id}/name`, { nomGroupe });

      // Update group composition
      await axios.put(`http://localhost:5000/api/groupes/${id}/composition`, {
        etudiants: selectedEtudiants
      });

      alert("Groupe mis à jour avec succès");
      router.push('/gestion-groupes');
    } catch (err) {
      console.error("Erreur lors de la mise à jour du groupe :", err);
      alert(`Erreur: ${err.response?.data?.message || err.message}`);
    }
  };

  if (loading) {
    return <Layout title="Modifier le groupe"><p>Chargement...</p></Layout>;
  }

  if (!groupe) {
    return <Layout title="Modifier le groupe"><p>Groupe non trouvé</p></Layout>;
  }

  return (
    <Layout title={`Modifier le groupe ${groupe.nomGroupe}`}>
      <div className="p-4 max-w-4xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
          <h1 className="text-2xl font-bold mb-6 text-[#b17a56]">Modifier le groupe</h1>
          
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-1">Nom du groupe</label>
            <input
              type="text"
              value={nomGroupe}
              onChange={(e) => setNomGroupe(e.target.value)}
              className="w-full p-2 border rounded focus:ring-2 focus:ring-[#b17a56] focus:outline-none"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Étudiants disponibles */}
            <div className="bg-gray-50 p-4 rounded-lg">
              <h3 className="font-medium mb-3 text-gray-700">
                Étudiants disponibles ({etudiants.length})
              </h3>
              
              <div className="overflow-y-auto max-h-64 border rounded bg-white">
                {etudiants.length > 0 ? (
                  <ul className="divide-y divide-gray-200">
                    {etudiants.map(etudiant => (
                      <li 
                        key={etudiant.idEtudiant}
                        className={`p-2 cursor-pointer transition-colors flex justify-between items-center ${
                          selectedEtudiants.includes(etudiant.idEtudiant) 
                            ? 'bg-blue-50' 
                            : 'hover:bg-blue-50'
                        }`}
                        onClick={() => toggleSelection(etudiant.idEtudiant)}
                      >
                        <div className="flex items-center">
                          <PersonIcon className="text-gray-400 mr-2" style={{ fontSize: '1.2rem' }} />
                          <span>{etudiant.nom} {etudiant.prenom}</span>
                        </div>
                        <span className="text-xs text-gray-500">
                          {etudiant.idGroupe ? "(déjà dans ce groupe)" : ""}
                        </span>
                      </li>
                    ))}
                  </ul>
                ) : (
                  <div className="p-4 text-center text-gray-500">
                    Aucun étudiant disponible
                  </div>
                )}
              </div>
            </div>

            {/* Étudiants sélectionnés */}
            <div className="bg-gray-50 p-4 rounded-lg">
              <h3 className="font-medium mb-3 text-gray-700">
                Membres du groupe ({selectedEtudiants.length})
              </h3>
              
              <div className={`overflow-y-auto max-h-64 border rounded bg-white ${
                selectedEtudiants.length > 0 ? '' : 'flex items-center justify-center'
              }`}>
                {selectedEtudiants.length > 0 ? (
                  <ul className="divide-y divide-gray-200">
                    {selectedEtudiants.map(id => {
                      const etudiant = etudiants.find(e => e.idEtudiant === id);
                      if (!etudiant) return null;
                      
                      return (
                        <li 
                          key={id}
                          className="p-2 hover:bg-red-50 transition-colors flex justify-between items-center"
                        >
                          <div className="flex items-center">
                            <PersonIcon className="text-blue-400 mr-2" style={{ fontSize: '1.2rem' }} />
                            <span>{etudiant.nom} {etudiant.prenom}</span>
                          </div>
                          <button 
                            onClick={(e) => {
                              e.stopPropagation();
                              toggleSelection(id);
                            }}
                            className="text-red-500 hover:text-red-700 text-xs font-medium"
                          >
                            Retirer
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                ) : (
                  <div className="p-8 text-center text-gray-500">
                    Sélectionnez des étudiants pour les ajouter au groupe
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="mt-6 flex justify-end space-x-3">
            <button
              onClick={() => router.push('/gestion-groupes')}
              className="px-4 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400 transition-colors"
            >
              Annuler
            </button>
            <button
              onClick={updateGroupe}
              className="px-4 py-2 bg-[#b17a56] text-white rounded-lg hover:bg-[#8c6244] transition-colors flex items-center"
            >
              <SaveIcon className="mr-2" /> Enregistrer
            </button>
          </div>
        </div>
      </div>
    </Layout>
  );
}